// ABOUTME: 校验 Skill 的主题和链接，并从唯一真源生成 Claude 的薄入口，避免复制维护指导正文。
import { access, mkdir, readFile, writeFile } from "node:fs/promises";
import { realpathSync } from "node:fs";
import { dirname, isAbsolute, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import {
  guideCatalog,
  readGuide,
  repository,
  skillRelativePath,
} from "./guide.mjs";

const mirrorPath = ".claude/skills/floatboat-workbench/SKILL.md";
const marker =
  "<!-- Generated by pnpm skills:sync; edit .agents/skills/floatboat-workbench/SKILL.md. -->";
const missing = (error) => error?.code === "ENOENT";

async function expectedMirror(root) {
  const source = await readGuide("overview", root);
  const header = /^---\r?\n[\s\S]*?\r?\n---\r?\n/u.exec(source)?.[0];
  if (!header || !/^name: floatboat-workbench$/mu.test(header))
    throw new Error("SKILL_FRONTMATTER_INVALID");
  return `${header}\n${marker}\n\nRead and follow the [canonical Floatboat workbench skill](../../../.agents/skills/floatboat-workbench/SKILL.md). Resolve its references relative to that canonical skill directory. This entry uses the same repository-local guidance and requires no Floatboat installation.\n`;
}

export async function synchronizeSkill(root = repository) {
  const target = resolve(root, mirrorPath);
  const existing = await readFile(target, "utf8").catch((error) => {
    if (missing(error)) return null;
    throw error;
  });
  if (existing !== null && !existing.includes(marker))
    throw new Error(
      "SKILL_ENTRY_NOT_GENERATED: preserve the existing Claude skill and reconcile it first",
    );
  const expected = await expectedMirror(root);
  await mkdir(dirname(target), { recursive: true });
  if (existing !== expected) await writeFile(target, expected);
}

export async function checkSkill(root = repository) {
  const { directory, topics } = await guideCatalog(root);
  for (const file of new Set(Object.values(topics))) {
    const absolute = resolve(directory, file);
    const text = await readFile(absolute, "utf8");
    if (!text.trim()) throw new Error(`GUIDE_EMPTY:${file}`);
    for (const link of text.matchAll(/\[[^\]]*\]\(([^\s)]+)\)/gu)) {
      const href = link[1].split("#")[0];
      if (!href || /^https?:\/\//u.test(href)) continue;
      const target = resolve(dirname(absolute), href);
      const local = relative(root, target);
      if (
        isAbsolute(href) ||
        isAbsolute(local) ||
        local.split(sep).includes("..")
      )
        throw new Error(`SKILL_LINK_OUTSIDE_REPOSITORY:${file}`);
      await access(target).catch(() => {
        throw new Error(`SKILL_LINK_MISSING:${file}:${href}`);
      });
    }
  }
  const mirror = await readFile(resolve(root, mirrorPath), "utf8");
  if (mirror !== (await expectedMirror(root)))
    throw new Error("SKILL_ENTRY_STALE: run pnpm skills:sync");
  const agents = await readFile(resolve(root, "AGENTS.md"), "utf8");
  if (!agents.includes(`${skillRelativePath}/SKILL.md`))
    throw new Error("SKILL_AGENT_ENTRY_MISSING");
  return Object.keys(topics).length;
}

if (
  process.argv[1] &&
  realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  const args = process.argv.slice(2).filter((arg) => arg !== "--");
  void (async () => {
    if (
      args.length > 1 ||
      (args[0] && !["--write", "--check"].includes(args[0]))
    )
      throw new Error(
        "Usage: node tooling/workbench-skill.mjs [--check|--write]",
      );
    if (args[0] === "--write") await synchronizeSkill();
    const topics = await checkSkill();
    console.log(
      `Workbench skill checked: ${topics} topics; Codex source and Claude entry agree.`,
    );
  })().catch((error) => {
    console.error(error.message);
    process.exitCode = 1;
  });
}
